/**
 * Imagens de fora (todas de uso livre).
 * - Grama: "Seamless grass texture II" de athile, OpenGameArt, licença CC0
 *   (https://opengameart.org/content/seamless-grass-texture-ii). Reduzida para 256 px e com menos saturação.
 * - Soldados e cavaleiros: desenhados no próprio código (soldiers.ts, pixelart.ts), sem imagem de fora.
 * - Dragão (31/out, de volta a pedido do Agostinho): folha de sprites em pixel art que ele mandou (arte/dragao.png:
 *   pousado, voando e cuspindo fogo, 6 quadros cada, 103 × 110). Recortada e sem fundo; 31/out: tirado o
 *   contorno branco que sobrou do fundo cinza e posto um contorno escuro de 1 px, como o resto da pixel art. AUTOR E LICENÇA A CONFERIR
 *   antes de publicar o jogo (ver docs/RISCOS.md). Sem a imagem, o jogo usa o dragão desenhado no código.
 */
export const DRAGON_PNG = "data:image/png;base64,";
export const GRASS_JPG = "data:image/jpeg;base64,";

const images: Record<string, HTMLImageElement> = {};
let ready = false;
let loading: Promise<void> | null = null;

/** Carrega as imagens; o campo é repintado quando elas chegam. */
export function loadAssets(): Promise<void> {
  if (loading) return loading;
  const load = (key: string, src: string): Promise<void> => {
    const img = new Image();
    img.src = src;
    images[key] = img;
    return img.decode().then(
      () => undefined,
      () => undefined
    );
  };
  loading = Promise.all([load("grass", GRASS_JPG), load("dragon", DRAGON_PNG)]).then(() => {
    ready = true;
  });
  return loading;
}

export function assetsReady(): boolean {
  return ready;
}

export function grassImage(): HTMLImageElement | null {
  return ready ? images.grass : null;
}

export function dragonImage(): HTMLImageElement | null {
  return ready && images.dragon && images.dragon.naturalWidth > 0 ? images.dragon : null;
}
